$( document ).ready(function() {
    $('#municipalitySelect .typeahead').typeahead({
            hint: true,
            highlight: true,
            minLength: 1,
            restrictInputToDatum: true
        },
        {
            name: 'municipalites',
            source: muni,
            display: "name"
    }
    ).bind('typeahead:select', function(ev, suggestion) {
            $('#muni_code').val(suggestion.id);
            $('#submit').css('visibility', 'visible');
    }).bind('typeahead:change', function(typeAheadInput,typeAheadValue){

        if(typeAheadValue.length > 0) {
            let matches = muni.index.search(typeAheadValue);

            if (matches.length === 1) {

                $('#municipalitySelect .typeahead').val(matches[0].name);
                $('#muni_code').val(matches[0].id);
                $('#submit').css('visibility', 'visible');
            } else if (matches.length > 1){
                let foundIndex = -1;

                $.each(matches, function(i, match){ if(match.name === typeAheadValue) foundIndex = i; });
                if(foundIndex === -1) {
                    clearSelection();
                } else {
